<?php /* Template Name: Applicant Portal */ get_header();$logged=is_user_logged_in();$login=wp_login_url(nvconsult_theme_url('applicant-portal'));$lost=wp_lostpassword_url(nvconsult_theme_url('applicant-portal')); ?><section class="nv-content nv-portal-page"><div class="nv-wrap"><div class="nv-eyebrow"><?php esc_html_e('Your NVConsult account','nvconsult'); ?></div><h1><?php esc_html_e('Applicant Portal','nvconsult'); ?></h1><p class="nv-lead"><?php esc_html_e('Track applications, complete document requests and communicate with your consultant in one place.','nvconsult'); ?></p><?php if(!$logged): ?><div class="nv-account-grid"><div class="nv-card"><h2><?php esc_html_e('Sign in','nvconsult'); ?></h2><p><?php esc_html_e('Already have an account? Sign in securely through WordPress.','nvconsult'); ?></p><a class="nv-btn nv-full" href="<?php echo esc_url($login); ?>"><?php esc_html_e('Sign in','nvconsult'); ?></a><a class="nv-text-link" href="<?php echo esc_url($lost); ?>"><?php esc_html_e('Forgot password?','nvconsult'); ?></a></div><div class="nv-card"><h2><?php esc_html_e('Create applicant account','nvconsult'); ?></h2><form id="nv-register-form" class="nv-form"><label><?php esc_html_e('Full name','nvconsult'); ?><input name="name" required autocomplete="name"></label><label><?php esc_html_e('Email','nvconsult'); ?><input type="email" name="email" required autocomplete="email"></label><label><?php esc_html_e('Password','nvconsult'); ?><input type="password" name="password" minlength="10" required autocomplete="new-password"></label><button class="nv-btn nv-full" type="submit"><?php esc_html_e('Create account','nvconsult'); ?></button><p id="nv-register-feedback" class="nv-feedback" aria-live="polite"></p></form></div></div><?php else: ?><div class="nv-portal-actions"><span><?php printf(esc_html__('Signed in as %s','nvconsult'),esc_html(wp_get_current_user()->display_name)); ?></span><a href="<?php echo esc_url(wp_logout_url(home_url('/'))); ?>"><?php esc_html_e('Sign out','nvconsult'); ?></a></div><details class="nv-card nv-claim"><summary><?php esc_html_e('Link an existing application','nvconsult'); ?></summary><p><?php esc_html_e('If you applied before creating your account, enter the application number and tracking token you received.','nvconsult'); ?></p><form id="nv-claim-form" class="nv-form"><label><?php esc_html_e('Application number','nvconsult'); ?><input type="number" name="application_id" min="1" required></label><label><?php esc_html_e('Tracking token','nvconsult'); ?><textarea name="tracking_token" required></textarea></label><button class="nv-btn" type="submit"><?php esc_html_e('Link application','nvconsult'); ?></button><p id="nv-claim-feedback" class="nv-feedback" aria-live="polite"></p></form></details><?php if(shortcode_exists('nvconsult_applicant_portal'))echo do_shortcode('[nvconsult_applicant_portal]');else echo '<div class="nv-card"><strong>'.esc_html__('NVConsult Core must be activated to use the applicant portal.','nvconsult').'</strong></div>';endif; ?></div></section><script>document.addEventListener('DOMContentLoaded',()=>{const post=async(u,b)=>{const r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/json','X-WP-Nonce':'<?php echo esc_js(wp_create_nonce('wp_rest')); ?>'},body:JSON.stringify(b)}),d=await r.json();if(!r.ok)throw new Error(d.message||'Request failed');return d};const rf=document.getElementById('nv-register-form');if(rf)rf.addEventListener('submit',async e=>{e.preventDefault();const o=document.getElementById('nv-register-feedback');o.textContent='<?php echo esc_js(__('Creating account…','nvconsult')); ?>';try{await post('<?php echo esc_url(rest_url('nvconsult/v1/applicant/register')); ?>',Object.fromEntries(new FormData(rf).entries()));o.innerHTML='<?php echo esc_js(__('Account created.','nvconsult')); ?> <a href="<?php echo esc_url($login); ?>"><?php echo esc_js(__('Sign in now','nvconsult')); ?></a>'}catch(x){o.textContent=x.message}});const cf=document.getElementById('nv-claim-form');if(cf)cf.addEventListener('submit',async e=>{e.preventDefault();const o=document.getElementById('nv-claim-feedback');o.textContent='<?php echo esc_js(__('Linking application…','nvconsult')); ?>';try{await post('<?php echo esc_url(rest_url('nvconsult/v1/applicant/claim')); ?>',Object.fromEntries(new FormData(cf).entries()));o.textContent='<?php echo esc_js(__('Application linked. Reloading your portal…','nvconsult')); ?>';location.reload()}catch(x){o.textContent=x.message}})});</script><?php get_footer(); ?>
